  var methods       = restMethods.concat(socketMethods)

  function randomAction() {
    return getRandom(methods)
  }

  function randomPrice(symbol, side) {
    var delta = side === 'buy' ? numberBetween(-200, 20) / 100 : numberBetween(-20, 200) / 100
